<?php

declare(strict_types=1);

use PhpCsFixer\Config;
use PhpCsFixer\Finder;

$product = require __DIR__.'/modules.php';

$finder = (new Finder())
    // config/reference.php is generated by the container build.
    ->notPath('reference.php')
    ->in([
        __DIR__.'/Framework',
        ...array_map(
            static fn (string $module): string => __DIR__.'/'.$product['namespace'].'/'.$module,
            $product['modules'],
        ),
        __DIR__.'/bin',
        __DIR__.'/config',
        __DIR__.'/public',
        __DIR__.'/tests',
        __DIR__.'/tools',
    ])
    ->append([
        __DIR__.'/modules.php',
        __DIR__.'/phparkitect.php',
        __DIR__.'/phpstan.modules.php',
        __DIR__.'/rector.php',
    ]);

return (new Config())
    ->setRiskyAllowed(true)
    ->setRules([
        '@Symfony' => true,
        // Pinned, so a fixer upgrade cannot change the style. PER wins for the rules
        // both sets define, except the import order set right below.
        '@PER-CS3x0' => true,
        'ordered_imports' => [
            'sort_algorithm' => 'alpha',
            'imports_order' => ['class', 'function', 'const'],
        ],
        'declare_strict_types' => true,
    ])
    ->setCacheFile(__DIR__.'/var/.php-cs-fixer.cache')
    ->setFinder($finder);
